import { KnowledgeGraph } from '../graph/graph';
import type { Intent } from '../ui/payload';
import type { Focus } from './focus';

/**
 * Prompt bubbles, derived from graph state rather than generated by a model: instant,
 * free, and guaranteed to be questions the linker and router can actually handle.
 */
export function suggestPrompts(g: KnowledgeGraph, focus: Focus, intent: Intent): string[] {
  const out: string[] = [];
  const label = (id?: string) => (id ? g.node(id)?.label : undefined);
  const gene = g.typed(focus.geneId ?? '', 'Gene')?.props.symbol;
  const variant = label(focus.variantId);
  const patient = label(focus.patientId);
  const organ = label(focus.organId)?.toLowerCase();

  if (intent === 'edit_design') out.push('What has not been assessed for this edit?');

  if (patient && focus.diseaseId) {
    const status = g.outEdges(focus.patientId!, 'HAS_FINDING').find((e) => e.to === focus.diseaseId)?.props.status;
    if (intent !== 'explain_diagnosis' && intent !== 'inheritance') {
      out.push(`Why is ${patient} ${status === 'carrier' ? 'a carrier' : 'affected'}?`);
    }
  }
  if (variant && intent !== 'edit_design') out.push(`What edit options fit ${variant}?`);
  if (gene && intent !== 'evidence') out.push(`What does recent research say about editing ${gene}?`);
  if (gene && intent !== 'gene_overview') out.push(`Which organs does ${gene} act in?`);
  if (organ) out.push(`Which genes act in the ${organ}?`);
  if (patient && intent === 'explain_diagnosis') out.push(`Is ${patient} a carrier or affected, and why?`);

  // Fallbacks so the first view is never empty.
  const firstOrgan = g.ofType('Organ')[0]?.label.toLowerCase();
  const firstPatient = g.ofType('Patient')[0]?.label;
  const firstVariant = g.ofType('Variant').find((v) => v.props.locus)?.label;
  if (firstOrgan) out.push(`Which genes act in the ${firstOrgan}?`);
  if (firstPatient) out.push(`Why is ${firstPatient} affected?`);
  if (firstVariant) out.push(`What edit options fit ${firstVariant}?`);

  return [...new Set(out)].slice(0, 3);
}
